#!/usr/bin/env python3
"""Regenerate the real-run examples in analyzer/docs/output.md.

Builds the small collection of host `ws01` in a temporary directory, runs the analyzer's
`detect --json --files` and `timeline` on it in this process, and puts the output between
the marker comments of each example block:

    <!-- generated by analyzer/tools/regenerate_examples.py: detect-json -->
    <!-- end generated: detect-json -->

    python3 analyzer/tools/regenerate_examples.py           # rewrite the document
    python3 analyzer/tools/regenerate_examples.py --check   # exit 1 when a block is stale

The collection's temporary path is printed as `/cases/ws01/ws01`; every other key and value
is what the run wrote. Every time in the collection is fixed, so the output is the same on
every run, platform and Python version. "Regenerating the output examples" in
analyzer/docs/development.md documents the collection and the options.

Exit status: 0 when the document is current or was rewritten, 1 when `--check` found a
stale block, 2 when a marker is missing, duplicated or out of order or a run fails.
"""

from __future__ import annotations

import argparse
import contextlib
import difflib
import hashlib
import io
import json
import os
import sys
import tempfile
from pathlib import Path

ANALYZER = Path(__file__).resolve().parent.parent
if str(ANALYZER) not in sys.path:
    sys.path.insert(0, str(ANALYZER))

# Imported after the analyzer directory joins the path, so the tool runs from any directory.
from doubleagent import cli  # noqa: E402
from doubleagent.errors import DoubleAgentError  # noqa: E402

DOCUMENT = ANALYZER / "docs" / "output.md"
SHOWN_INPUT = "/cases/ws01/ws01"
BLOCKS = ("detect-json", "inventory-json")
BEGIN = "<!-- generated by analyzer/tools/regenerate_examples.py: %s -->"
END = "<!-- end generated: %s -->"

# The first Claude Code prompt, in epoch seconds; the other file times follow it.
BASE_TIME = 1790848800
CLAUDE_PROJECT_SESSION = "11111111-2222-4333-8444-555555555555"
CLAUDE_LOOSE_SESSION = "99999999-8888-4777-8666-555555555555"


class MarkerError(DoubleAgentError):
    """A block's marker comments are missing, duplicated or out of order."""


class RunError(DoubleAgentError):
    """An analyzer command exited with a failure, so its output is no example."""


def _jsonl(records: list[dict]) -> str:
    return "".join(json.dumps(record) + "\n" for record in records)


def _claude_transcript(session_id: str, cwd: str | None, minute: int) -> str:
    """Return a Claude Code transcript of one prompt, one tool call and its result."""
    common: dict = {"sessionId": session_id, "version": "2.1.289", "userType": "external"}
    if cwd is not None:
        common.update(cwd=cwd, gitBranch="main")

    def stamp(second: int) -> str:
        return "2026-10-01T10:%02d:%02d.000Z" % (minute, second)

    def assistant(uuid: str, second: int, blocks: list[dict]) -> dict:
        message: dict = {"model": "claude-fable-5-1", "id": "msg_" + uuid, "role": "assistant"}
        message.update(type="message", content=blocks)
        return dict(common, type="assistant", uuid=uuid, timestamp=stamp(second), message=message)

    def user(uuid: str, second: int, content: object) -> dict:
        message = {"role": "user", "content": content}
        return dict(common, type="user", uuid=uuid, timestamp=stamp(second), message=message)

    call: dict = {"type": "tool_use", "id": "toolu_%02d" % minute, "name": "Bash"}
    call["input"] = {"command": "ls", "description": "List files"}
    result = {"tool_use_id": call["id"], "type": "tool_result", "content": "README.md"}
    return _jsonl(
        [
            user("u1", 0, "list the files here"),
            assistant("a1", 1, [{"type": "text", "text": "Listing them."}, call]),
            user("u2", 2, [result]),
            assistant("a2", 3, [{"type": "text", "text": "There is one file, README.md."}]),
        ]
    )


def _claude_history() -> str:
    """Return `history.jsonl` with prompts no transcript records, in two projects and none."""
    return _jsonl(
        [
            {
                "display": "summarise the open issues",
                "pastedContents": {},
                "timestamp": (BASE_TIME - 3600) * 1000,
                "project": "/srv/proj",
            },
            {
                "display": "why does the build fail",
                "pastedContents": {},
                "timestamp": (BASE_TIME - 7200) * 1000,
                "project": "/srv/gone",
            },
            {"display": "what is a tarball", "pastedContents": {}, "timestamp": BASE_TIME * 1000},
        ]
    )


# user, home, agent, path relative to the home, content.
FILES: list[tuple[str, str, str, str, str]] = [
    ("alice", "/home/alice", "claude-code", ".claude/history.jsonl", _claude_history()),
    (
        "alice",
        "/home/alice",
        "claude-code",
        ".claude/projects/-srv-proj/%s.jsonl" % CLAUDE_PROJECT_SESSION,
        _claude_transcript(CLAUDE_PROJECT_SESSION, "/srv/proj", 0),
    ),
    (
        "alice",
        "/home/alice",
        "claude-code",
        ".claude/projects/-/%s.jsonl" % CLAUDE_LOOSE_SESSION,
        _claude_transcript(CLAUDE_LOOSE_SESSION, None, 5),
    ),
    ("alice", "/home/alice", "amp", ".config/amp/settings.json", "{}"),
    ("bob", "/home/bob", "gemini-cli", ".gemini/settings.json", "{}"),
    ("bob", "/home/bob", "gemini-cli", ".gemini/tmp/chats/gone.json", '{"messages": []}'),
    ("bob", "/home/bob", "ollama", ".ollama/history", "why is the sky blue\n/bye\n"),
    (
        "alice",
        "/srv/proj",
        "aider",
        ".aider.input.history",
        "\n# 2026-10-02 12:00:05.123456\n+add tests\n",
    ),
    ("alice", "/srv/proj", "cursor", ".cursor/rules/style.mdc", "use tabs\n"),
    ("alice", "/srv/proj", "project", "AGENTS.md", "# agents\n"),
    ("alice", "/srv/shared", "project", "AGENTS.md", "# agents\n"),
]
# Collected rows whose file is left out of fs/, as if it was lost after the collection.
MISSING = {"/home/bob/.gemini/tmp/chats/gone.json"}
UIDS = {"alice": 1000, "bob": 1001}
# A manifest row cut short, as a collection copied while the collector was writing it would be;
# it goes between the home rows and the project rows.
CUT_ROW = '{"user":"bob","home":"/home/bob","agent":"ollama","path":"/home/bob/.ollama/con'


def _manifest_row(user: str, home: str, agent: str, rel: str, data: bytes, mtime: int) -> dict:
    path = home + "/" + rel
    return {
        "user": user,
        "home": home,
        "agent": agent,
        "path": path,
        "archive_path": "fs" + path,
        "type": "file",
        "size": len(data),
        "mtime": mtime,
        "atime": mtime,
        "ctime": mtime,
        "btime": mtime,
        "uid": UIDS[user],
        "gid": UIDS[user],
        "mode": "644",
        "sha256": hashlib.sha256(data).hexdigest(),
        "secret": False,
        "status": "collected",
        "target": "",
        "error": "",
    }


def build_collection(root: Path) -> Path:
    """Write the `ws01` collection under `root` and return its directory.

    Args:
        root: An empty directory; the collection is written to `root/ws01`.

    Returns:
        The collection directory, holding `collection.json`, `manifest.jsonl` and `fs/`.
    """
    collection = root / "ws01"
    (collection / "fs").mkdir(parents=True)
    rows: list[str] = []
    for index, (user, home, agent, rel, text) in enumerate(FILES):
        mtime = BASE_TIME + 600 + index
        data = text.encode("utf-8")
        rows.append(json.dumps(_manifest_row(user, home, agent, rel, data, mtime)))
        if home + "/" + rel in MISSING:
            continue
        disk = collection / ("fs" + home + "/" + rel)
        disk.parent.mkdir(parents=True, exist_ok=True)
        disk.write_bytes(data)
        os.utime(disk, (mtime, mtime))
    first_project = next(i for i, entry in enumerate(FILES) if entry[1].startswith("/srv/"))
    rows.insert(first_project, CUT_ROW)
    (collection / "manifest.jsonl").write_text("\n".join(rows) + "\n", encoding="utf-8")
    summary = {
        "tool": "collect-agent-artifacts",
        "version": "1.19.0",
        "hostname": "ws01",
        "mode": "live",
        "root": "/",
        "users": ["alice", "bob"],
        "homes": ["/home/alice", "/home/bob"],
        "users_with_artifacts": ["alice", "bob"],
        "projects": ["/srv/proj", "/srv/shared"],
        "started": "2026-10-01T10:20:00Z",
        "finished": "2026-10-01T10:20:05Z",
        "archive": "ws01.tar.gz",
    }
    (collection / "collection.json").write_text(json.dumps(summary, indent=2), encoding="utf-8")
    return collection


def _run(argv: list[str]) -> str:
    stdout, stderr = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
        status = cli.main(argv)
    if status != 0:
        raise RunError("%s exited %s: %s" % (argv[0], status, stderr.getvalue().strip()))
    return stdout.getvalue()


def _show_input(text: str, collection: Path) -> str:
    # The longer form first: on macOS the temporary path /var/... resolves to /private/var/...
    for form in sorted({str(collection.resolve()), str(collection)}, key=len, reverse=True):
        text = text.replace(json.dumps(form)[1:-1], SHOWN_INPUT)
    return text


def generate() -> dict[str, str]:
    """Run the analyzer on a fresh `ws01` collection.

    Returns:
        Each block name mapped to its fenced `json` block, ending with a line feed.

    Raises:
        RunError: The `detect` or `timeline` run failed.
    """
    with tempfile.TemporaryDirectory(prefix="doubleagent-examples-") as work:
        collection = build_collection(Path(work))
        detect = _run(["detect", str(collection), "--json", "--files"])
        out = Path(work) / "out"
        _run(["timeline", str(collection), "-o", str(out)])
        inventory = (out / "inventory.json").read_text(encoding="utf-8")
        outputs = {"detect-json": detect, "inventory-json": inventory}
        return {
            name: "```json\n%s\n```\n" % _show_input(text, collection).rstrip("\n")
            for name, text in outputs.items()
        }


def _span(text: str, name: str) -> tuple[int, int]:
    """Return the start and end offsets of what lies between the markers of block `name`."""
    begin, end = BEGIN % name + "\n", "\n" + END % name
    if text.count(begin) != 1 or text.count(end) != 1:
        raise MarkerError(
            "block %s needs one line %s and one %s" % (name, BEGIN % name, END % name)
        )
    start = text.index(begin) + len(begin)
    stop = text.index(end) + 1
    if stop < start:
        raise MarkerError("block %s ends before it begins" % name)
    return start, stop


def render(text: str, blocks: dict[str, str]) -> str:
    """Return `text` with each block's markers enclosing its new content.

    Raises:
        MarkerError: A block's markers are missing, duplicated or out of order.
    """
    for name in BLOCKS:
        start, stop = _span(text, name)
        text = text[:start] + blocks[name] + text[stop:]
    return text


def check(document: Path = DOCUMENT) -> list[str]:
    """Return a unified diff per stale block of `document`, empty when every block is current.

    Raises:
        MarkerError: A block's markers are missing, duplicated or out of order.
        RunError: The `detect` or `timeline` run failed.
    """
    text = document.read_text(encoding="utf-8")
    blocks = generate()
    diffs = []
    for name in BLOCKS:
        start, stop = _span(text, name)
        if text[start:stop] != blocks[name]:
            lines = difflib.unified_diff(
                text[start:stop].splitlines(keepends=True),
                blocks[name].splitlines(keepends=True),
                "%s (%s, documented)" % (document, name),
                "%s (%s, regenerated)" % (document, name),
            )
            diffs.append("".join(lines))
    return diffs


def regenerate(document: Path = DOCUMENT) -> None:
    """Rewrite every generated block of `document` from a fresh run.

    Raises:
        MarkerError: A block's markers are missing, duplicated or out of order.
        RunError: The `detect` or `timeline` run failed.
    """
    text = render(document.read_text(encoding="utf-8"), generate())
    with open(document, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(text)


def main(argv: list[str] | None = None) -> int:
    """Run the command line and return the exit status."""
    parser = argparse.ArgumentParser(description="Regenerate the real-run examples of output.md.")
    parser.add_argument("--check", action="store_true", help="report stale blocks, write nothing")
    parser.add_argument("--document", type=Path, default=DOCUMENT, help="default: %(default)s")
    args = parser.parse_args(argv)
    try:
        if not args.check:
            regenerate(args.document)
            return 0
        diffs = check(args.document)
    except (MarkerError, RunError) as error:
        print("error: %s" % error, file=sys.stderr)
        return 2
    for diff in diffs:
        sys.stdout.write(diff)
    if diffs:
        print("stale; run python3 analyzer/tools/regenerate_examples.py", file=sys.stderr)
    return 1 if diffs else 0


if __name__ == "__main__":
    sys.exit(main())
